import { useRef, useState, useEffect } from 'react'
import {
  getSysCommunityList,
  addSysCommunity,
  editSysCommunity,
  deleteSysCommunity,
  updateSysCommunityStatus,
} from '@/apis/admin/system-config'
import ExcelTable from '@/components/exportExcel'
import { ActionType, ProColumns, ModalForm, ProFormText, ProFormDigit, ProFormSelect,ProForm } from '@ant-design/pro-components'
import {
  Button,
  Popconfirm,
  message,
  Tag,
  Space,
  Tooltip
} from 'antd'
import {
  PlusOutlined,
  EditOutlined,
  DeleteOutlined,
  CheckCircleOutlined,
  StopOutlined,
  HomeOutlined,
  EnvironmentOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import AreaCascader from '@/components/AreaCascader'

// 状态映射
const statusMap: Record<number, { text: string; color: string }> = {
  1: { text: '启用', color: 'success' },
  2: { text: '禁用', color: 'default' },
}

const Community: React.FC = () => {
  const actionRef = useRef<ActionType>()
  const [modalVisible, setModalVisible] = useState(false)
  const [modalTitle, setModalTitle] = useState('添加小区')
  const [editingRecord, setEditingRecord] = useState<any>(null)
  const [formSubmitting, setFormSubmitting] = useState(false)
  const [areaValues, setAreaValues] = useState<string[]>([])
  const [areaLabels, setAreaLabels] = useState<string[]>([])

  // 打开新增弹窗
  const handleAdd = () => {
    setEditingRecord(null)
    setAreaValues([])
    setAreaLabels([])
    setModalTitle('添加小区')
    setModalVisible(true)
  }

  // 打开编辑弹窗
  const handleEdit = (record: any) => {
    setEditingRecord(record)
    // 设置地区值
    if (record.provinceId && record.cityId && record.districtId) {
      setAreaValues([String(record.provinceId), String(record.cityId), String(record.districtId)])
      setAreaLabels([record.provinceName, record.cityName, record.districtName])
    } else {
      setAreaValues([])
      setAreaLabels([])
    }
    setModalTitle('编辑小区')
    setModalVisible(true)
  }

  // 保存小区
  const handleSave = async (values: any) => {
    if (areaValues.length < 3) {
      message.error('请选择完整的所属地区')
      return
    }

    setFormSubmitting(true)
    try {
      const submitData = {
        communityName: values.communityName,
        sort: values.sort,
        status: values.status,
        remark: values.remark || '',
        provinceId: Number(areaValues[0]),
        provinceName: areaLabels[0],
        cityId: Number(areaValues[1]),
        cityName: areaLabels[1],
        districtId: Number(areaValues[2]),
        districtName: areaLabels[2],
      }

      if (editingRecord) {
        // 编辑
        const res = await editSysCommunity(editingRecord.id, {
          id: editingRecord.id,
          ...submitData
        })
        if (res.code === ResultEnum.SUCCESS) {
          message.success('保存成功')
          setModalVisible(false)
          actionRef.current?.reload()
        } else {
          message.error('保存失败')
        }
      } else {
        // 新增
        const res = await addSysCommunity(submitData)
        if (res.code === ResultEnum.SUCCESS) {
          message.success('新增成功')
          setModalVisible(false)
          actionRef.current?.reload()
        } else {
          message.error('新增失败')
        }
      }
    } catch (e) {
      console.error('保存小区失败:', e)
      message.error('操作失败')
    } finally {
      setFormSubmitting(false)
    }
  }

  // 更新状态
  const handleUpdateStatus = async (record: any, newStatus: number) => {
    try {
      // 如果有设备关联且要禁用，给出提示
      if (newStatus === 2 && record.deviceCount > 0) {
        message.warning(`该小区已关联 ${record.deviceCount} 个设备，禁用后新设备不可再选择该小区`)
      }

      const res = await updateSysCommunityStatus(record.id, { id: record.id })
      if (res.code === ResultEnum.SUCCESS) {
        message.success(newStatus === 1 ? '启用成功' : '禁用成功')
        actionRef.current?.reload()
      } else {
        message.error('操作失败')
      }
    } catch (e) {
      console.error('更新状态失败:', e)
      message.error('操作失败')
    }
  }

  // 删除小区
  const handleDelete = async (record: any) => {
    try {
      const res = await deleteSysCommunity(record.id, { id: record.id })
      if (res.code === ResultEnum.SUCCESS) {
        message.success('删除成功')
        actionRef.current?.reload()
      } else {
        message.error('删除失败')
      }
    } catch (e) {
      console.error('删除小区失败:', e)
      message.error('操作失败')
    }
  }

  // 地区选择变化
  const handleAreaChange = (result: { labels: string[]; values: string[] }) => {
    setAreaValues(result.values)
    setAreaLabels(result.labels)
  }

  // 表格列定义
  const columns: ProColumns<any>[] = [
    {
      title: '小区ID',
      dataIndex: 'id',
      key: 'id',
      width: 100,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>
          {text}
        </span>
      ),
    },
    {
      title: '小区名称',
      dataIndex: 'communityName',
      key: 'communityName',
      width: 160,
      render: (text) => (
        <Space>
          <HomeOutlined style={{ color: '#1890ff' }} />
          <span>{text}</span>
        </Space>
      ),
    },
    {
      title: '所属地区',
      dataIndex: 'areaName',
      key: 'areaName',
      width: 200,
      hideInSearch: true,
      render: (_, record) => (
        <Space>
          <EnvironmentOutlined style={{ color: '#52c41a' }} />
          <span>{record.provinceName}{record.cityName}{record.districtName}</span>
        </Space>
      ),
    },
    {
      title: '关联设备数',
      dataIndex: 'deviceCount',
      key: 'deviceCount',
      width: 120,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>{text || 0}</span>
      ),
    },
    {
      title: '排序值',
      dataIndex: 'sort',
      key: 'sort',
      width: 100,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>{text}</span>
      ),
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 100,
      valueType: 'select',
      valueEnum: {
        1: { text: '启用', status: 'Success' },
        2: { text: '禁用', status: 'Default' },
      },
      render: (_, record) => {
        const status = statusMap[record.status]
        return <Tag color={status?.color || 'default'}>{status?.text || '未知'}</Tag>
      },
    },
    {
      title: '备注',
      dataIndex: 'remark',
      key: 'remark',
      width: 180,
      hideInSearch: true,
      ellipsis: true,
      render: (text) => text || '-',
    },
    {
      title: '操作',
      key: 'option',
      valueType: 'option',
      fixed: 'right',
      width: 140,
      render: (_, record) => [
        <Tooltip title="编辑" key={`${record.id}-edit`}>
          <Button
            type="link"
            title="编辑"
            icon={<EditOutlined />}
            onClick={() => handleEdit(record)}
          />
        </Tooltip>,
        record.status === 1 ? (
          <Tooltip title="禁用" key={`${record.id}-disable`}>
            <Popconfirm
              title="确定要禁用该小区吗？"
              description={record.deviceCount > 0 ? `该小区已关联 ${record.deviceCount} 个设备，禁用后新设备不可再选择该小区` : undefined}
              onConfirm={() => handleUpdateStatus(record, 2)}
              okText="确定"
              cancelText="取消"
            >
              <Button type="link" danger title="禁用" icon={<StopOutlined />} />
            </Popconfirm>
          </Tooltip>
        ) : (
          <Tooltip title="启用" key={`${record.id}-enable`}>
            <Button
              type="link"
              title="启用"
              icon={<CheckCircleOutlined />}
              style={{ color: '#52c41a' }}
              onClick={() => handleUpdateStatus(record, 1)}
            />
          </Tooltip>
        ),
        <Tooltip title="删除" key={`${record.id}-delete`}>
          <Popconfirm
            title="确定要删除该小区吗？"
            description={record.deviceCount > 0 ? '该小区已被设备引用，无法直接删除，请先禁用或迁移设备' : '删除后不可恢复'}
            onConfirm={() => handleDelete(record)}
            okText="确定"
            cancelText="取消"
            disabled={record.deviceCount > 0}
          >
            <Button
              type="link"
              danger
              title="删除"
              icon={<DeleteOutlined />}
              disabled={record.deviceCount > 0}
            />
          </Popconfirm>
        </Tooltip>,
      ],
    },
  ]

  return (
    <>
      <ExcelTable
        key="community-list"
        columns={columns}
        requestFn={async () => {
          return await getSysCommunityList()
        }}
        actionRef={actionRef}
        rowSelection={false}
        options={{
          fullScreen: false,
          reload: true,
          setting: false,
          density: false
        }}
        search={false}
        toolBarRenderFn={() => [
          <Button
            key="add"
            type="primary"
            icon={<PlusOutlined />}
            onClick={handleAdd}
          >
            添加小区
          </Button>,
        ]}
        scroll={{ x: 1000 }}
      />

      {/* 新增/编辑弹窗 */}
      <ModalForm
        title={
          <Space>
            <HomeOutlined style={{ color: '#1890ff' }} />
            {modalTitle}
          </Space>
        }
        open={modalVisible}
        onOpenChange={(visible) => {
          if (!visible) {
            setAreaValues([])
            setAreaLabels([])
          }
          setModalVisible(visible)
        }}
        onFinish={handleSave}
        initialValues={editingRecord ? {
          communityName: editingRecord.communityName,
          sort: editingRecord.sort,
          status: editingRecord.status,
          remark: editingRecord.remark
        } : {
          status: 1
        }}
        submitter={{
          submitButtonProps: {
            loading: formSubmitting,
          },
        }}
        layout="horizontal"
        labelCol={{ flex: '0 0 100px' }}
        wrapperCol={{ flex: '1 1 auto' }}
        width={560}
      >
        <ProFormText
          name="communityName"
          label="小区名称"
          placeholder="例如：阳光花园"
          rules={[{ required: true, message: '请输入小区名称' }]}
        />
        <ProForm.Item
          label="所属地区"
          required
          rules={[{
            validator: () => {
              if (areaValues.length < 3) {
                return Promise.reject(new Error('请选择完整的所属地区'))
              }
              return Promise.resolve()
            }
          }]}
        >
          <AreaCascader
            value={areaLabels}
            onChange={handleAreaChange}
            placeholder="请选择省/市/区"
            asyncMode={true}
          />
        </ProForm.Item>
        <ProFormDigit
          name="sort"
          label="排序值"
          min={0}
          fieldProps={{ style: { width: 200 } }}
          rules={[{ required: true, message: '请输入排序值' }]}
        />
        <ProFormSelect
          name="status"
          label="状态"
          options={[
            { label: '启用', value: 1 },
            { label: '禁用', value: 2 },
          ]}
          rules={[{ required: true, message: '请选择状态' }]}
        />
        <ProFormText
          name="remark"
          label="备注"
          placeholder="可选"
        />
      </ModalForm>
    </>
  )
}

export default Community